import React from "react";
import { useLanguage } from "../i18n/LanguageContext";

export default function ContentStatus({ loading, error, retry }) {
  const { language } = useLanguage();
  if (error) return <div role="alert"><p>{language === "kk" ? "Деректерді жүктеу мүмкін болмады." : "Не удалось загрузить данные."}</p><button onClick={retry}>{language === "kk" ? "Қайталау" : "Попробовать снова"}</button></div>;
  return loading ? <p role="status">{language === "kk" ? "Жүктелуде…" : "Загрузка…"}</p> : null;
}
